NEW_FILES = {'tests/test_grocery_aisle_sign.py': '"""The aisle sign\'s `grocery` form: a supermarket\'s numbered aisle marker (1.131.0).\n\nThe walker, 2026-10-26: grocery comps with a numbered sign over every aisle naming what is down it (the factory\'s\ndocs/reference/GROCERY_STORE_COMPS.md). `aisle_sign` was the card shop\'s hand-lettered marker board, its words card\nshop words. The `grocery` form prints the aisle\'s number -- the variant\'s, aisle 1 at variant 0 -- large in a ruled\nbox and two lines of categories beside it, white on blue; the card shop\'s form is unchanged.\n\nFAILS ON 1.130.0: the genome has no `grocery` form and four variants, and `card_brands` has no grocery lines.\n\nRun:  python -m pytest tests/test_grocery_aisle_sign.py\n"""\nimport json\nimport os\n\nfrom zoo_keeper.core import card_art as CA\nfrom zoo_keeper.core import card_brands as CB\nfrom zoo_keeper.core import flat_art as FA\nfrom zoo_keeper.core import flat_forms as FF\n\nGENOME = os.path.join(os.path.dirname(__file__), "..", "zoo_keeper", "genome", "species", "aisle_sign.json")\n\n\ndef test_the_genome_offers_the_form_and_a_variant_an_aisle():\n    g = json.load(open(GENOME, encoding="utf-8"))\n    assert g["params"]["form"] == ["auto", "grocery"]\n    assert g["module_variants"] == len(CB.GROCERY_AISLE_SAYS) == 12\n\n\ndef test_the_variant_is_the_aisles_number_and_its_lines():\n    for v in (0, 4, 11):\n        got = FF.plan_aisle_sign(1.4, 0.05, 0.6, {"form": "grocery"}, v)\n        face = got["tiles"]["face"]\n        assert face["number"] == v + 1 == got["facts"]["number"]\n        assert tuple(face["lines"]) == CB.GROCERY_AISLE_SAYS[v]\n\n\ndef test_the_marker_is_printed_white_on_blue():\n    got = FF.plan_aisle_sign(1.4, 0.05, 0.6, {"form": "grocery"}, 2)\n    c = CA.paint(dict(got["tiles"]["face"]))\n    px = [tuple(c.buf[i:i + 3]) for i in range(0, len(c.buf), 3)]\n    blue = sum(1 for p in px if p == FA.GROCERY_GROUND)\n    ink = sum(1 for p in px if p == FA.GROCERY_INK)\n    assert blue > ink > 0\n\n\ndef test_each_grocery_variant_is_its_own_module():\n    """`test_flat_art`\'s rule for a variant -- a different module in geometry, not only in its tile -- held to the\n    grocery form\'s twelve."""\n    shapes = set()\n    for v in range(len(CB.GROCERY_AISLE_SAYS)):\n        got = FF.plan_aisle_sign(1.4, 0.05, 0.6, {"form": "grocery"}, v)\n        shapes.add(tuple(sorted((p["part"], tuple(p["verts"][0])) for p in got["prims"])))\n    assert len(shapes) == len(CB.GROCERY_AISLE_SAYS)\n\n\ndef test_the_card_shops_form_is_unchanged():\n    got = FF.plan_aisle_sign(1.1, 0.05, 0.4, {}, 0)\n    assert got["tiles"]["face"]["kind"] == "aisle" and "number" not in got["tiles"]["face"]\n    assert got["facts"]["says"] == CB.AISLE_SAYS[0]\n\n\ndef test_every_grocery_line_is_painted_and_held_by_the_denylist():\n    painted = CA.painted_strings()\n    for pair in CB.GROCERY_AISLE_SAYS:\n        for line in pair:\n            assert line in painted, line\n'}
CHANGELOG = "## [1.131.0] - the aisle sign's `grocery` form: a supermarket's numbered aisle marker\n\nThe walker, 2026-10-26: grocery comps with a printed sign over the head of every aisle, its number large and what is\ndown it beside it. They are filed as the factory's docs/reference/GROCERY_STORE_COMPS.md. `aisle_sign` was the card\nshop's hand-lettered marker board, lettered with card-shop words.\n\n### Added\n- **`aisle_sign` form `grocery`** (`flat_forms.plan_aisle_sign`, `flat_art.grocery_marker`):\n  - the aisle's NUMBER, the variant's (aisle 1 is variant 0), large in a white-ruled box at the hoist end;\n  - two lines of what is down the aisle beside it;\n  - white on a 1990s chain's blue, printed rather than hand-lettered.\n- **`card_brands.GROCERY_AISLE_SAYS`**: twelve aisles' lines, in the order a store walks them. They are categories\n  only, never a product or a brand, and are painted through `card_art.painted_strings`, so the denylist test holds\n  them.\n- **The genome**: `params.form` `auto` / `grocery`, `module_variants` 4 -> 12.\n  - A variant is its own module in geometry too (`test_flat_art`): the grocery form's drops step in 5 mm an aisle.\n  - The card-shop form's variants 0-3 are as they shipped; past them its drops step out 5 mm a round.\n\n### Tests\n- `tests/test_grocery_aisle_sign.py`:\n  - the genome offers the form and twelve variants;\n  - the variant is the aisle's number and its lines;\n  - the marker is printed white on blue;\n  - each grocery variant is its own module;\n  - the card shop's form is unchanged;\n  - every grocery line is painted and held by the denylist.\n\n  Fails on 1.130.0.\n\n"
OLD_VERSION, NEW_VERSION = '1.130.0', '1.131.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
